775	//  bare mixer output (residual=False) into `mix_out` [kSeq,d]. Uses sm scratch.
776	//  Mirrors mamba3_oracle.layer_forward (residual OFF).
777	// ════════════════════════════════════════════════════════════════════════
778	__device__ inline void mb_mixer_fwd(const MambaWeights::Layer& L,
779	                            const float* __restrict__ xn,   // [kSeq,d] (mixer input)
780	                            MambaSampleSmem::LayerAct* a,
781	                            float* __restrict__ mix_out,     // [kSeq,d] OUT
782	                            MambaSampleSmem* sm) {
783	    // xz = in_proj(xn); split rows [0,d_inner)->x_in, [d_inner,2di)->z.
784	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
785	        const int s = idx / mb::kDInner, o = idx % mb::kDInner;
786	        const float* xr = xn + (int64_t)s * mb::kD;
787	        const float* Wr0 = L.in_w + (int64_t)o * mb::kD;
788	        const float* Wr1 = L.in_w + (int64_t)(mb::kDInner + o) * mb::kD;
789	        float a0 = 0.f, a1 = 0.f;
790	        #pragma unroll 4
791	        for (int k = 0; k < mb::kD; ++k) { float xv = xr[k]; a0 += xv * Wr0[k]; a1 += xv * Wr1[k]; }
792	        a->x_in[s][o] = a0;       // = x_main (NO conv, NO SiLU)
793	        a->z[s][o] = a1;
794	    }
795	    __syncthreads();
796	    // x_proj(x_in) -> sm->xproj [kSeq,xproj]; split into the SSM params.
797	    mb_linear(&a->x_in[0][0], mb::kDInner, mb::kDInner, L.x_proj_w, nullptr,
798	              mb::kXProj, &sm->xproj[0][0], mb::kXProj);
799	    // route the splits into the LayerAct caches.
800	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kXProj; idx += blockDim.x) {
801	        const int s = idx / mb::kXProj, o = idx % mb::kXProj;
802	        const float v = sm->xproj[s][o];
803	        if (o < mb::kOffAmod) a->dt_lr[s][o - mb::kOffDtLr] = v;
804	        else if (o < mb::kOffThet) a->A_mod[s][o - mb::kOffAmod] = v;
805	        else if (o < mb::kOffULam) a->theta[s][o - mb::kOffThet] = v;
806	        else if (o < mb::kOffBr) a->u_lam[s][o - mb::kOffULam] = v;
807	        else if (o < mb::kOffBi) a->Br[s][o - mb::kOffBr] = v;
808	        else if (o < mb::kOffCr) a->Bi[s][o - mb::kOffBi] = v;
809	        else if (o < mb::kOffCi) a->Cr[s][o - mb::kOffCr] = v;
810	        else a->Ci[s][o - mb::kOffCi] = v;
811	    }
812	    __syncthreads();
813	    // dt_pre = dt_proj(dt_lr) + bias  [kSeq, n_heads] (PER HEAD).
814	    mb_linear(&a->dt_lr[0][0], mb::kDtRank, mb::kDtRank, L.dt_proj_w, L.dt_proj_b,
815	              mb::kNHeads, &a->dt_pre[0][0], mb::kNHeads);
816	    // BCNorm (RMSNorm over Nc) + biases -> Bbar=(Br2,Bi2), Cbar=(Cr2,-Ci2). The
817	    //   normed output lands in sm->adj_a at WIDTH-kStateC stride (s*Nc+c), NOT the
818	    //   [kSeq][kDInner] field stride — read it back with the same Nc stride.
819	    float* an = &sm->adj_a[0][0];
820	    mb_rmsnorm_fwd(&a->Br[0][0], L.B_norm_w, an, &sm->adj_b[0][0], &a->Br_r[0], sm->red, mb::kStateC, mb::kStateC);
821	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
822	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
823	        a->Bbar[s][c][0] = an[s * mb::kStateC + c] + L.B_bias[c];
824	    }
825	    __syncthreads();
826	    mb_rmsnorm_fwd(&a->Bi[0][0], L.Bhat_norm_w, an, &sm->adj_b[0][0], &a->Bi_r[0], sm->red, mb::kStateC, mb::kStateC);
827	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
828	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
829	        a->Bbar[s][c][1] = an[s * mb::kStateC + c] + L.Bhat_bias[c];
830	    }
831	    __syncthreads();
832	    mb_rmsnorm_fwd(&a->Cr[0][0], L.C_norm_w, an, &sm->adj_b[0][0], &a->Cr_r[0], sm->red, mb::kStateC, mb::kStateC);
833	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
834	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
835	        a->Cbar[s][c][0] = an[s * mb::kStateC + c] + L.C_bias[c];
836	    }
837	    __syncthreads();
838	    mb_rmsnorm_fwd(&a->Ci[0][0], L.Chat_norm_w, an, &sm->adj_b[0][0], &a->Ci_r[0], sm->red, mb::kStateC, mb::kStateC);
839	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
840	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
841	        a->Cbar[s][c][1] = -(an[s * mb::kStateC + c] + L.Chat_bias[c]);   // Cbar imag = -(Ci2)
842	    }
843	    __syncthreads();
844	    // selective scan -> a->y_scan.
845	    mb_scan_fwd(L.A_log, a, &a->y_scan[0][0]);
846	    // y_gated = (y_scan + x_in*D) * silu(z) -> sm->adj_a ; out = out_proj(y_gated).
847	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
848	        const int s = idx / mb::kDInner, c = idx % mb::kDInner;
849	        float yv = a->y_scan[s][c] + a->x_in[s][c] * L.D[c];
850	        sm->adj_a[s][c] = yv * mb_silu(a->z[s][c]);
851	    }
852	    __syncthreads();
853	    mb_linear(&sm->adj_a[0][0], mb::kDInner, mb::kDInner, L.out_w, nullptr,
854	              mb::kD, mix_out, mb::kD);
855	}
856	
857	// ════════════════════════════════════════════════════════════════════════
858	//  SwiGLU forward for one sample. Input h1n = RMSNorm_mlp(h1). Caches g_pre,u_mlp.
859	//  out = down(silu(gate(x)) * up(x)). Mirrors mamba3_oracle.swiglu_forward.
860	// ════════════════════════════════════════════════════════════════════════
861	__device__ inline void mb_swiglu_fwd(const MambaWeights::Layer& L,
862	                             const float* __restrict__ h1n,   // [kSeq,d]
863	                             MambaSampleSmem::LayerAct* a,
864	                             float* __restrict__ mlp_out,      // [kSeq,d] OUT
865	                             MambaSampleSmem* sm) {
866	    mb_linear(h1n, mb::kD, mb::kD, L.gate_w, nullptr, mb::kDff, &a->g_pre[0][0], mb::kDff);
867	    mb_linear(h1n, mb::kD, mb::kD, L.up_w,   nullptr, mb::kDff, &a->u_mlp[0][0], mb::kDff);
868	    // prod = silu(g_pre) * u -> sm->wff_a.
869	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDff; idx += blockDim.x) {
870	        const int s = idx / mb::kDff, o = idx % mb::kDff;
871	        sm->wff_a[s][o] = mb_silu(a->g_pre[s][o]) * a->u_mlp[s][o];
872	    }
873	    __syncthreads();
874	    mb_linear(&sm->wff_a[0][0], mb::kDff, mb::kDff, L.down_w, nullptr, mb::kD, mlp_out, mb::kD);
875	}
876	
877	// ════════════════════════════════════════════════════════════════════════
878	//  FORWARD for one sample (CTA-cooperative). Mirrors mamba3_oracle.model_forward
879	//  + block_forward. Caches BOTH blocks' activations into sm->act[li]. Returns NLL.
880	// ════════════════════════════════════════════════════════════════════════
881	__device__ inline float mb_forward_sample(const MambaWeights& w, const int* tokens_s,
882	                                    int target, MambaSampleSmem* sm) {
883	    // Embedding + positional -> layer_in[0].
884	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
885	        const int s = idx / mb::kD, j = idx % mb::kD;
886	        sm->layer_in[0][s][j] = w.tok[(int64_t)tokens_s[s] * mb::kD + j]
887	                              + w.pos[(int64_t)s * mb::kD + j];
888	    }
889	    __syncthreads();
890	
891	    for (int li = 0; li < mb::kLayers; ++li) {
892	        const MambaWeights::Layer& L = w.layer[li];
893	        MambaSampleSmem::LayerAct* a = &sm->act[li];
894	        float* hin = &sm->layer_in[li][0][0];   // block input (residual)
895	        // --- mixer sub-block: h1 = hin + mixer(RMSNorm_mix(hin)) ---
896	        // xhat written to throwaway scratch (adj_c) — only the recip is cached; the
897	        // backward recomputes xhat from the raw block input layer_in[li].
898	        mb_rmsnorm_fwd(hin, L.mixn_w, &sm->dr[0][0], &sm->adj_c[0][0], &a->mixn_r[0],
899	                       sm->red, mb::kD, mb::kD);   // xn -> sm->dr
900	        // mix_out written into adj_b at WIDTH-kD stride (s*kD+j); read it the same way.
901	        float* mo = &sm->adj_b[0][0];
902	        mb_mixer_fwd(L, &sm->dr[0][0], a, mo, sm);   // mix_out -> sm->adj_b (kD-strided)
903	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
904	            const int s = idx / mb::kD, j = idx % mb::kD;
905	            a->h1[s][j] = hin[s * mb::kD + j] + mo[s * mb::kD + j];   // h1 = x + mixer_out
906	        }
907	        __syncthreads();
908	        // --- SwiGLU sub-block: h2 = h1 + mlp(RMSNorm_mlp(h1)) ---
909	        // xhat throwaway (adj_c); backward recomputes from the raw h1.
910	        mb_rmsnorm_fwd(&a->h1[0][0], L.mlpn_w, &sm->dr[0][0], &sm->adj_c[0][0], &a->mlpn_r[0],
911	                       sm->red, mb::kD, mb::kD);   // h1n -> sm->dr
912	        mb_swiglu_fwd(L, &sm->dr[0][0], a, mo, sm);  // mlp_out -> sm->adj_b (kD-strided)
913	        float* dst = (li + 1 < mb::kLayers) ? &sm->layer_in[li + 1][0][0] : &sm->final_in[0][0];
914	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
915	            const int s = idx / mb::kD, j = idx % mb::kD;
916	            dst[s * mb::kD + j] = a->h1[s][j] + mo[s * mb::kD + j];   // h2 = h1 + mlp_out
917	        }
918	        __syncthreads();
919	    }
920	
921	    // Final RMSNorm (LAST position) + head -> logits -> NLL.
922	    const float* hlast = &sm->final_in[mb::kSeq - 1][0];
923	    float ss = 0.0f;
924	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) { float v = hlast[j]; ss += v * v; }
925	    float ms = mb_block_sum(ss, sm->red) / (float)mb::kD;
926	    float r = rsqrtf(ms + mb::kRmsEps);
927	    if (threadIdx.x == 0) sm->fn_r[mb::kSeq - 1] = r;
928	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
929	        float xh = hlast[j] * r;
930	        sm->fn_xhat[mb::kSeq - 1][j] = xh;
931	        sm->adj_a[0][j] = xh * w.norm_w[j];   // hn (RMSNorm, NO bias) -> adj_a[0]
932	    }
933	    __syncthreads();
934	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
935	        const float* Wr = w.out_w + (int64_t)o * mb::kD;
936	        float acc = w.out_b[o];
937	        #pragma unroll 4
938	        for (int k = 0; k < mb::kD; ++k) acc += sm->adj_a[0][k] * Wr[k];
939	        sm->logits[o] = acc;
940	    }
941	    __syncthreads();
942	    float lmax = -CUDART_INF_F;
943	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) lmax = fmaxf(lmax, sm->logits[o]);
944	    lmax = mb_block_max(lmax, sm->red);
945	    float es = 0.0f;
946	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) es += __expf(sm->logits[o] - lmax);
947	    es = mb_block_sum(es, sm->red);
948	    float logz = lmax + __logf(es);
949	    return logz - sm->logits[target];
950	}
