500	    return (int64_t)2 * kMambaNumTensors
501	         + sg2_ws_stride<MbSG2Dims>((int64_t)kMbSG2Nmax);
502	}
503	__host__ __device__ __forceinline__ int64_t mb_tc_sg2_floats(int nCTA) {
504	    // +1 for the 8-byte realignment slack of sg2_ws_base (kMambaTotalElems is odd, so
505	    // the per-CTA int64 row_off64 prefix may need a +1 bump to land 8-byte aligned).
506	    return (int64_t)nCTA * mb_sg2_ws_stride_floats() + 1;
507	}
508	__host__ __device__ __forceinline__ int64_t mb_tc_workspace_floats(int T, int nCTA) {
509	    (void)T;
510	    // MAMBA-3 scalar design: the per-CTA partial is the FULL grad [total] (not the
511	    // acts + tile-scratch + dW-split + non-GEMM-partial of the old wgmma Fork-B).
512	    // Layout order MUST match the kernel's pointer derivations:
513	    //   [nCTA*total | loss(nCTA) | loss_out(1) | opt_reduce(2nCTA+1) |
514	    //    sam_backup+sam_grad(2*total) | muon | sg2 (| profiler)].
515	    return (int64_t)nCTA * kMambaTotalElems          // per-CTA FULL grad partial
516	         + nCTA + 1                                  // loss slots + reduced loss
517	         + mb_tc_opt_reduce_floats(nCTA)             // STAGED-opt (Prodigy) reduce slots
518	         + mb_tc_looksam_floats()                    // SAM 2nd-bwd scratch [sam_backup|sam_grad]
519	         + mb_tc_muon_floats(nCTA)                   // Muon NS per-matrix scratch
520	         + mb_tc_sg2_floats(nCTA)                    // SuperGrok2 meta-net per-CTA scratch (carve-LAST)
521	#if SG_MB_TC_PROFILE
522	         + (int64_t)nCTA * SG_MBTC_PROF_SLOTS * 2 + 2  // phase-profiler (doubles=2 floats) + align pad
523	#endif
524	         ;
525	}
