527	template <OptId Opt>
528	__global__ void SG_MBTC_LAUNCH_BOUNDS
529	fused_mamba_megakernel_tc(PersistentContext ctx,
530	                          float* __restrict__ params,
531	                          MambaTokenCtx tok,
532	                          float* __restrict__ grad,
533	                          float lr, int step, FusedOptState st) {
534	    // MAMBA-3 design: the "TC" megakernel runs the VALIDATED scalar per-sample
535	    // fwd+bwd (model_stage_mamba3.cuh, mb_forward_sample/mb_backward_sample —
536	    // matched to the fp64 oracle to ~2e-6) batch-parallel into a per-CTA FULL-grad
537	    // partial, then a deterministic ascending-CTA reduce + the canonical optimizer
538	    // tail (incl. the SAM 2nd backward for looksam/SG/SG2). The Mamba-3 mixer is
539	    // scan-dominated (the projections are a tiny share of the wall), so the scalar
540	    // engine IS the production path; the wgmma-projection dW machinery is bypassed.
541	    // The per-sample MambaSampleSmem (~227 KB) lives in DYNAMIC smem (opt-in by the
542	    // launcher), exactly like the scalar Mamba megakernel.
543	    extern __shared__ char mamba_tc_smem_raw[];
544	    MambaSampleSmem& sm = *reinterpret_cast<MambaSampleSmem*>(mamba_tc_smem_raw);
545	    GridBarrier bar = ctx.barrier();
546	    constexpr bool kSamCoupled = (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
547	                                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2);
548	    (void)kSamCoupled;
549	    const int cta = blockIdx.x;
550	    const int nCTA = (int)ctx.n_ctas;
551	    const int B = tok.B;
552	    const int T = B * mb::kSeq;
553	    (void)T;
554	
555	    // Workspace partition. The per-CTA partial is the FULL grad [total] (scalar
556	    // design), NOT the dW-output-stationary split + non-GEMM partial. acts/scratch/
557	    // dw_part are unused on this path (kept zero-width in mb_tc_workspace_floats).
558	    float* ws = tok.workspace;
559	    const int64_t total_p = kMambaTotalElems;
560	    float* part_base = ws;                                  // [nCTA * total]
561	    float* loss_part = part_base + (int64_t)nCTA * total_p; // [nCTA]
562	    float* loss_out  = loss_part + nCTA;                    // [1]
563	    float* dw_part   = loss_out + 1;                        // unused (kept for layout parity)
564	    (void)dw_part;
565	    // STAGED-opt (Prodigy P2.6) cross-CTA reduce slots: [r slots | s slots | reduced d]
566	    // = 2*nCTA+1. Carved after the loss slot (dw_part is zero-width here).
567	    float* opt_reduce = loss_out + 1;
568	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Prodigy reduce slots (mamba has
569	    // NO Muon region — unlike the decoder/vit twins — so this follows opt_reduce; term
570	    // order matches mb_tc_workspace_floats). Carving it here keeps every prior region's
571	    // offset unchanged, so the already-green cells are byte-identical. Layout:
572	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
573	    float* sam_backup = opt_reduce + mb_tc_opt_reduce_floats(nCTA);
574	    float* sam_grad   = sam_backup + kMambaTotalElems;
575	    // Muon NS per-matrix scratch, carved AFTER the LookSAM sam scratch (term order matches
576	    // mb_tc_workspace_floats — carving it LAST [before the optional profiler] keeps every
577	    // prior region's offset unchanged, so the already-green mamba cells are byte-identical).
578	    // Unused unless Opt==Muon. Layout (mirrors the decoder/vit twins):
579	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kMbMuonMaxNumel)
