        const bool active = (b < B);
        if (active) {
            if (threadIdx.x < mb::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * mb::kSeq + threadIdx.x];
            if (threadIdx.x == 0) tgt_s = tok.targets[b];
